            expect(variablesByElement['totalProcessed'].mandatory).toBe(true)
            expect(variablesByElement['totalProcessed'].active).toBe(true)

            expect(variablesByElement['highPriorityCount']).toBeDefined()
            expect(variablesByElement['highPriorityCount'].internal_type).toBe('integer')
            expect(variablesByElement['highPriorityCount'].mandatory).toBe(true)
            expect(variablesByElement['highPriorityCount'].active).toBe(true)

            expect(variablesByElement['normalPriorityCount']).toBeDefined()
            expect(variablesByElement['normalPriorityCount'].internal_type).toBe('integer')
            expect(variablesByElement['normalPriorityCount'].mandatory).toBe(true)
            expect(variablesByElement['normalPriorityCount'].active).toBe(true)

