            expect(triggers.length).toBe(1)

            const trigger = triggers[0]
            expect(trigger.sys_id).toBe('96bd6a7ad88542fea2eb94623c4eedba')

            const triggerInputs = unzipInputArray(trigger.trigger_inputs)

            const tableInput = findInput(triggerInputs, 'table')
            expect(tableInput).toBeDefined()
            expect(tableInput.value).toBe('problem') // Changed from 'incident'

            const conditionInput = findInput(triggerInputs, 'condition')
            expect(conditionInput).toBeDefined()
            expect(conditionInput.value).toBe('active=true^assignment_groupISEMPTY^NQpriority=1')

            const strategyInput = findInput(triggerInputs, 'trigger_strategy')
