            const lookUpInputs = unzipInputArray(lookUpAction.values)

            const lookupTableInput = findInput(lookUpInputs, 'table')
            expect(lookupTableInput.value).toBe('problem') // Changed from 'incident'

            const conditionsInput = findInput(lookUpInputs, 'conditions')
            expect(conditionsInput.value).toBe('assignment_groupISEMPTY^active=true^NQpriority=1^ORDERBYpriority')

            const maxResultsInput = findInput(lookUpInputs, 'max_results')
            expect(maxResultsInput.value).toBe(1000)

            // NEW Notification Action Added
            const notificationAction = actions.find((a) => a.sys_id === 'a1b2c3d4e5f6789012345678abcdef90')
