            expect(updateP4P5).toBeDefined()
            const updateP4P5Inputs = unzipInputArray(updateP4P5.values)
            const updateP4P5Values = findInput(updateP4P5Inputs, 'values')
            expect(updateP4P5Values.value).toContain('P4 or P5 created')

            // Validate table_name for updateRecord actions
            const updateP1Table = findInput(updateP1Inputs, 'table_name')
            expect(updateP1Table.value).toBe('incident')

            const updateP2Table = findInput(updateP2Inputs, 'table_name')
            expect(updateP2Table.value).toBe('incident')

            const updateP3Table = findInput(updateP3Inputs, 'table_name')
            expect(updateP3Table.value).toBe('incident')

            const updateP4P5Table = findInput(updateP4P5Inputs, 'table_name')
            expect(updateP4P5Table.value).toBe('incident')

            // Validate "No unassigned incidents" updateRecord action (inside if block)
            const updateNoIncidents = actions.find((a) => a.ui_id === '337006a0-0223-4d79-91aa-fe2ce41a021b')
            expect(updateNoIncidents).toBeDefined()
            const updateNoIncidentsInputs = unzipInputArray(updateNoIncidents.values)
            const updateNoIncidentsValues = findInput(updateNoIncidentsInputs, 'values')
            expect(updateNoIncidentsValues.value).toContain('No Un assigned incidents')
            const updateNoIncidentsTable = findInput(updateNoIncidentsInputs, 'table_name')
            expect(updateNoIncidentsTable.value).toBe('incident')

            // lookUpRecords action validation with content
            const lookupAction = actions.find((a) => a.ui_id === 'f3118178-31d2-456d-8dc8-7a00ae5ec749')
            expect(lookupAction).toBeDefined()

            const lookupInputs = unzipInputArray(lookupAction.values)
            const lookupTableInput = findInput(lookupInputs, 'table')
            expect(lookupTableInput.value).toBe('incident')

            const lookupConditionsInput = findInput(lookupInputs, 'conditions')
            expect(lookupConditionsInput.value).toContain('assignment_groupISEMPTY')

            const lookupMaxResultsInput = findInput(lookupInputs, 'max_results')
