            // Log actions validation with content
            const logActions = actions.filter((a) => a.action_type === '5bc1bcc6531003003bf1d9109ec587d4')
            expect(logActions.length).toBeGreaterThanOrEqual(9)

            // Validate specific log actions
            const startLog = actions.find((a) => a.ui_id === '1edb09e1-8456-4a89-ad77-168b13fcbe6d')
