            const startLogInputs = unzipInputArray(startLog.values)
            const startLogMessage = findInput(startLogInputs, 'log_message')
            expect(startLogMessage.value).toContain('Monthly Incident Processor started')

            const p1Log = actions.find((a) => a.ui_id === 'd2829217-fc64-4abd-bfc4-482656ea18a1')
            expect(p1Log).toBeDefined()
            const p1LogInputs = unzipInputArray(p1Log.values)
            const p1LogLevel = findInput(p1LogInputs, 'log_level')
